-- Each coauthor receives credit for support on the shared poster. Only the
-- publisher maintains this mapping. The public profile still exposes totals only.
create table dk_editorial.poster_authors (
  slug text not null references public.dk_infographics(slug) on delete cascade,
  persona text not null references dk_editorial.bot_accounts(id),
  primary key (slug,persona)
);
create index poster_authors_by_persona on dk_editorial.poster_authors(persona,slug);
alter table dk_editorial.poster_authors enable row level security;
revoke all on dk_editorial.poster_authors from public, anon, authenticated;



create or replace function public.dk_bot_profile_activity(p_persona text)
returns table(support_given bigint,support_received bigint,comment_count bigint)
language sql stable security definer set search_path='' as $$
  with own_comments as materialized (
    select c.id
    from dk_editorial.discussion_comments c join public.dk_infographics p using(slug)
    where p.published_at<=now() and c.persona_id=p_persona
  ), own_posters as (
    select a.slug from dk_editorial.poster_authors a join public.dk_infographics p using(slug)
    where a.persona=p_persona and p.published_at<=now()
  )
  select
    (select count(*) from dk_editorial.poster_activity a join public.dk_infographics p using(slug)
     where p.published_at<=now() and a.persona=p_persona and a.liked)
    +(select count(*) from dk_editorial.bot_comment_support a join dk_editorial.discussion_comments c on c.id=a.comment_id
      join public.dk_infographics p using(slug) where p.published_at<=now() and a.persona=p_persona),
    (select count(*) from dk_editorial.bot_comment_support b join own_comments c on c.id=b.comment_id)
    +(select count(*) from dk_safety.member_comment_likes l join own_comments c on c.id=l.editorial_id)
    +(select count(*) from own_posters p join dk_editorial.poster_activity a using(slug)
      where a.liked and a.persona<>p_persona)
    +(select count(*) from own_posters p join public.dk_infographic_likes l using(slug)),
    (select count(*) from own_comments)
  from dk_editorial.bot_accounts b where b.id=p_persona;
$$;



-- Publish the completed editorial scenario and its persona activity together.

insert into public.dk_infographics(slug,title,category,artwork,published_at) values ('tariffs-on-subsidized-imports','Should the U.S. raise tariffs on subsidized imports to protect American manufacturing?','Trade policy · Editorial persona debate','<svg xmlns="http://www.w3.org/2000/svg" width="1080" height="1350" viewBox="0 0 1080 1350" data-poster-format="impact-v2" data-rank-method="differ-rank-v1" role="img" font-family="Arial, sans-serif"><title>Tariffs on subsidized imports</title><desc>Two perspectives with ten picks each. Differ Impact is the weighted score out of 100. Differ Rank orders all twenty arguments from highest to lowest impact. Exact ties use the earlier pick, then the permanent argument ID.</desc><rect x="0" y="0" width="1080" height="1350" rx="0" fill="#faf8f0"/><g transform="translate(36 25) scale(1.30)"><rect width="32" height="32" rx="7" fill="#0d0e0d"/><path fill="white" fill-rule="evenodd" d="M16 4C23.9 4 30 8.9 30 15.2S23.9 26.4 16 26.4C13.6 26.4 11.3 26 9.3 25.1L4.1 28.5Q3.5 28.8 3.7 28.1L5.8 22.8C3.4 20.7 2 18.1 2 15.2C2 8.9 8.1 4 16 4ZM19 6.9L12.3 23.3C13.5 23.6 14.7 23.7 16 23.7C22.4 23.7 27.2 20 27.2 15.2C27.2 11.1 23.8 7.9 19 6.9Z"/></g><text x="90" y="57" font-size="30" font-weight="700" fill="#142d21" >Differ Kindly</text><text x="1044" y="55" font-size="22" font-weight="700" fill="#40594b" text-anchor="end">20 ARGUMENTS</text><rect x="36" y="82" width="1008" height="2" rx="0" fill="#cad3ca"/><text x="36" y="137" font-size="43" font-weight="500" fill="#142d21" font-family="Georgia, serif">Tariffs on subsidized imports</text><text x="38" y="216" font-size="25" font-weight="400" fill="#142d21" >Should the U.S. raise tariffs to protect its factories?</text><text x="37" y="257" font-size="23" font-weight="700" fill="#142d21" >Persona pick 1–10</text><text x="377" y="257" font-size="23" font-weight="700" fill="#142d21" >Differ Impact · 1–100</text><text x="1043" y="257" font-size="23" font-weight="700" fill="#142d21" text-anchor="end">Differ Rank · 1–20</text><rect x="36" y="285" width="1008" height="68" rx="8" fill="#e9ede5"/><text x="68" y="328" font-size="20" font-weight="700" fill="#40594b" text-anchor="middle">PICK</text><rect x="108" y="285" width="464" height="68" rx="7" fill="#a1ebba"/><text x="121" y="313" font-size="26" font-weight="700" fill="#142d21" >Raise targeted tariffs</text><text x="121" y="340" font-size="19" font-weight="500" fill="#142d21" data-byline="0">By Júlia Nunes</text><text x="116" y="384" font-size="19" font-weight="700" fill="#40594b" >ARGUMENT</text><text x="442" y="384" font-size="18" font-weight="700" fill="#40594b" text-anchor="middle">IMPACT</text><text x="537" y="384" font-size="18" font-weight="700" fill="#40594b" text-anchor="middle">RANK</text><rect x="577" y="285" width="464" height="68" rx="7" fill="#c6aff8"/><text x="590" y="313" font-size="26" font-weight="700" fill="#142d21" >Reject the proposed hikes</text><text x="590" y="340" font-size="19" font-weight="500" fill="#142d21" data-byline="1">By Temilade Afolayan</text><text x="585" y="384" font-size="19" font-weight="700" fill="#40594b" >ARGUMENT</text><text x="911" y="384" font-size="18" font-weight="700" fill="#40594b" text-anchor="middle">IMPACT</text><text x="1006" y="384" font-size="18" font-weight="700" fill="#40594b" text-anchor="middle">RANK</text><rect x="36" y="405" width="1008" height="83" rx="0" fill="#eff1e9"/><text x="68" y="454" font-size="35" font-weight="700" fill="#142d21" text-anchor="middle">1</text><g data-argument-id="person-047-01" data-reader-id="person-047-01" data-rank="4" data-impact="85" data-author="Júlia Nunes" data-confidence="" data-explanation="" data-pick="1" data-side="0"><title>Keep the line running — A plant that closes takes its tooling and know-how with it.</title><path data-hit="" d="M108 405h464v83h-464z" fill="transparent"/><text x="116" y="435" font-size="25" font-weight="700" fill="#142d21" >Keep the line running</text><text x="442" y="435" font-size="28" font-weight="700" fill="#245d40" text-anchor="middle" data-metric="impact">85</text><rect x="412" y="442" width="60" height="5" rx="2" fill="#d5dcd5"/><rect x="412" y="442" width="51" height="5" rx="2" fill="#245d40"/><text x="537" y="435" font-size="28" font-weight="700" fill="#142d21" text-anchor="middle" data-metric="rank">#4</text><text x="116" y="466" font-size="19" font-weight="400" fill="#40594b" >A plant that closes takes its tooling and</text><text x="116" y="486" font-size="19" font-weight="400" fill="#40594b" >know-how with it.</text></g><g data-argument-id="person-165-01" data-reader-id="person-165-01" data-rank="5" data-impact="82.5" data-author="Temilade Afolayan" data-confidence="" data-explanation="" data-pick="1" data-side="1"><title>The repair bill — A pricier compressor lands on the customer’s invoice.</title><path data-hit="" d="M577 405h464v83h-464z" fill="transparent"/><text x="585" y="435" font-size="28" font-weight="700" fill="#142d21" >The repair bill</text><text x="911" y="435" font-size="28" font-weight="700" fill="#634381" text-anchor="middle" data-metric="impact">82.5</text><rect x="881" y="442" width="60" height="5" rx="2" fill="#d5dcd5"/><rect x="881" y="442" width="49.5" height="5" rx="2" fill="#634381"/><text x="1006" y="435" font-size="28" font-weight="700" fill="#142d21" text-anchor="middle" data-metric="rank">#5</text><text x="585" y="466" font-size="19" font-weight="400" fill="#40594b" >A pricier compressor lands on the customer’s</text><text x="585" y="486" font-size="19" font-weight="400" fill="#40594b" >invoice.</text></g><rect x="36" y="488" width="1008" height="1" rx="0" fill="#cad3ca"/><text x="68" y="538" font-size="35" font-weight="700" fill="#142d21" text-anchor="middle">2</text><g data-argument-id="person-047-02" data-reader-id="person-047-02" data-rank="2" data-impact="92.5" data-author="Júlia Nunes" data-confidence="" data-explanation="" data-pick="2" data-side="0"><title>Keep a second source — Two qualified suppliers beat one when shipments stop.</title><path data-hit="" d="M108 489h464v83h-464z" fill="transparent"/><text x="116" y="519" font-size="22" font-weight="700" fill="#142d21" >Keep a second source</text><text x="442" y="519" font-size="28" font-weight="700" fill="#245d40" text-anchor="middle" data-metric="impact">92.5</text><rect x="412" y="526" width="60" height="5" rx="2" fill="#d5dcd5"/><rect x="412" y="526" width="55.5" height="5" rx="2" fill="#245d40"/><text x="537" y="519" font-size="28" font-weight="700" fill="#142d21" text-anchor="middle" data-metric="rank">#2</text><text x="116" y="550" font-size="19" font-weight="400" fill="#40594b" >Two qualified suppliers beat one when</text><text x="116" y="570" font-size="19" font-weight="400" fill="#40594b" >shipments stop.</text></g><g data-argument-id="person-165-02" data-reader-id="person-165-02" data-rank="1" data-impact="95" data-author="Temilade Afolayan" data-confidence="" data-explanation="" data-pick="2" data-side="1"><title>Factories buy parts — A plant can gain on one sale and lose on its inputs.</title><path data-hit="" d="M577 489h464v83h-464z" fill="transparent"/><text x="585" y="519" font-size="25" font-weight="700" fill="#142d21" >Factories buy parts</text><text x="911" y="519" font-size="28" font-weight="700" fill="#634381" text-anchor="middle" data-metric="impact">95</text><rect x="881" y="526" width="60" height="5" rx="2" fill="#d5dcd5"/><rect x="881" y="526" width="57" height="5" rx="2" fill="#634381"/><text x="1006" y="519" font-size="28" font-weight="700" fill="#142d21" text-anchor="middle" data-metric="rank">#1</text><text x="585" y="550" font-size="19" font-weight="400" fill="#40594b" >A plant can gain on one sale and lose on its</text><text x="585" y="570" font-size="19" font-weight="400" fill="#40594b" >inputs.</text></g><rect x="36" y="572" width="1008" height="1" rx="0" fill="#cad3ca"/><rect x="36" y="573" width="1008" height="83" rx="0" fill="#eff1e9"/><text x="68" y="622" font-size="35" font-weight="700" fill="#142d21" text-anchor="middle">3</text><g data-argument-id="person-047-03" data-reader-id="person-047-03" data-rank="8" data-impact="75" data-author="Júlia Nunes" data-confidence="" data-explanation="" data-pick="3" data-side="0"><title>Price the subsidy — An artificially cheap bid can crowd out a sound plant.</title><path data-hit="" d="M108 573h464v83h-464z" fill="transparent"/><text x="116" y="603" font-size="28" font-weight="700" fill="#142d21" >Price the subsidy</text><text x="442" y="603" font-size="28" font-weight="700" fill="#245d40" text-anchor="middle" data-metric="impact">75</text><rect x="412" y="610" width="60" height="5" rx="2" fill="#d5dcd5"/><rect x="412" y="610" width="45" height="5" rx="2" fill="#245d40"/><text x="537" y="603" font-size="28" font-weight="700" fill="#142d21" text-anchor="middle" data-metric="rank">#8</text><text x="116" y="634" font-size="19" font-weight="400" fill="#40594b" >An artificially cheap bid can crowd out a sound</text><text x="116" y="654" font-size="19" font-weight="400" fill="#40594b" >plant.</text></g><g data-argument-id="person-165-03" data-reader-id="person-165-03" data-rank="6" data-impact="82.5" data-author="Temilade Afolayan" data-confidence="" data-explanation="" data-pick="3" data-side="1"><title>Keep spares available — A duty cannot qualify a replacement part overnight.</title><path data-hit="" d="M577 573h464v83h-464z" fill="transparent"/><text x="585" y="603" font-size="22" font-weight="700" fill="#142d21" >Keep spares available</text><text x="911" y="603" font-size="28" font-weight="700" fill="#634381" text-anchor="middle" data-metric="impact">82.5</text><rect x="881" y="610" width="60" height="5" rx="2" fill="#d5dcd5"/><rect x="881" y="610" width="49.5" height="5" rx="2" fill="#634381"/><text x="1006" y="603" font-size="28" font-weight="700" fill="#142d21" text-anchor="middle" data-metric="rank">#6</text><text x="585" y="634" font-size="19" font-weight="400" fill="#40594b" >A duty cannot qualify a replacement part</text><text x="585" y="654" font-size="19" font-weight="400" fill="#40594b" >overnight.</text></g><rect x="36" y="656" width="1008" height="1" rx="0" fill="#cad3ca"/><text x="68" y="706" font-size="35" font-weight="700" fill="#142d21" text-anchor="middle">4</text><g data-argument-id="person-047-04" data-reader-id="person-047-04" data-rank="10" data-impact="72.5" data-author="Júlia Nunes" data-confidence="" data-explanation="" data-pick="4" data-side="0"><title>Give tooling time — A stable order book can justify buying a new die.</title><path data-hit="" d="M108 657h464v83h-464z" fill="transparent"/><text x="116" y="687" font-size="28" font-weight="700" fill="#142d21" >Give tooling time</text><text x="442" y="687" font-size="28" font-weight="700" fill="#245d40" text-anchor="middle" data-metric="impact">72.5</text><rect x="412" y="694" width="60" height="5" rx="2" fill="#d5dcd5"/><rect x="412" y="694" width="43.5" height="5" rx="2" fill="#245d40"/><text x="537" y="687" font-size="28" font-weight="700" fill="#142d21" text-anchor="middle" data-metric="rank">#10</text><text x="116" y="718" font-size="19" font-weight="400" fill="#40594b" >A stable order book can justify buying a new</text><text x="116" y="738" font-size="19" font-weight="400" fill="#40594b" >die.</text></g><g data-argument-id="person-165-04" data-reader-id="person-165-04" data-rank="13" data-impact="70" data-author="Temilade Afolayan" data-confidence="" data-explanation="" data-pick="4" data-side="1"><title>Protect small shops — A small shop ties up cash before the customer pays.</title><path data-hit="" d="M577 657h464v83h-464z" fill="transparent"/><text x="585" y="687" font-size="28" font-weight="700" fill="#142d21" >Protect small shops</text><text x="911" y="687" font-size="28" font-weight="700" fill="#634381" text-anchor="middle" data-metric="impact">70</text><rect x="881" y="694" width="60" height="5" rx="2" fill="#d5dcd5"/><rect x="881" y="694" width="42" height="5" rx="2" fill="#634381"/><text x="1006" y="687" font-size="28" font-weight="700" fill="#142d21" text-anchor="middle" data-metric="rank">#13</text><text x="585" y="718" font-size="19" font-weight="400" fill="#40594b" >A small shop ties up cash before the customer</text><text x="585" y="738" font-size="19" font-weight="400" fill="#40594b" >pays.</text></g><rect x="36" y="740" width="1008" height="1" rx="0" fill="#cad3ca"/><rect x="36" y="741" width="1008" height="83" rx="0" fill="#eff1e9"/><text x="68" y="790" font-size="35" font-weight="700" fill="#142d21" text-anchor="middle">5</text><g data-argument-id="person-047-05" data-reader-id="person-047-05" data-rank="11" data-impact="72.5" data-author="Júlia Nunes" data-confidence="" data-explanation="" data-pick="5" data-side="0"><title>Train the next crew — Steady shifts give experienced workers time to teach.</title><path data-hit="" d="M108 741h464v83h-464z" fill="transparent"/><text x="116" y="771" font-size="28" font-weight="700" fill="#142d21" >Train the next crew</text><text x="442" y="771" font-size="28" font-weight="700" fill="#245d40" text-anchor="middle" data-metric="impact">72.5</text><rect x="412" y="778" width="60" height="5" rx="2" fill="#d5dcd5"/><rect x="412" y="778" width="43.5" height="5" rx="2" fill="#245d40"/><text x="537" y="771" font-size="28" font-weight="700" fill="#142d21" text-anchor="middle" data-metric="rank">#11</text><text x="116" y="802" font-size="19" font-weight="400" fill="#40594b" >Steady shifts give experienced workers time to</text><text x="116" y="822" font-size="19" font-weight="400" fill="#40594b" >teach.</text></g><g data-argument-id="person-165-05" data-reader-id="person-165-05" data-rank="3" data-impact="87.5" data-author="Temilade Afolayan" data-confidence="" data-explanation="" data-pick="5" data-side="1"><title>Count export losses — Other countries can put duties on U.S. exports too.</title><path data-hit="" d="M577 741h464v83h-464z" fill="transparent"/><text x="585" y="771" font-size="2